[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$AggregatePath)
$ErrorActionPreference='Stop';$issues=[Collections.Generic.List[string]]::new();$a=Get-Content -Raw -Encoding UTF8 -LiteralPath $AggregatePath|ConvertFrom-Json
if($a.schemaVersion -ne 1){$issues.Add('SCHEMA_VERSION')};if($a.recordType -ne 'WebPageStudioUiEvidenceAggregate'){$issues.Add('RECORD_TYPE')};$layers=@($a.layers);if($layers.Count -ne 4){$issues.Add('LAYER_COUNT')};if(@($layers.layer|Sort-Object -Unique).Count -ne 4){$issues.Add('LAYER_ID_DUPLICATE')};if($a.decision -notin @('partial','accepted','blocked')){$issues.Add('DECISION_INVALID')};$pending=@($layers|Where-Object {$_.status -in @('not-run','review') -or $_.runtimeStatus -eq 'runtime-not-run'});$blocked=@($layers|Where-Object {$_.status -in @('blocked','failed')});if($a.decision -eq 'partial' -and ($pending.Count -eq 0 -or $blocked.Count -gt 0)){$issues.Add('PARTIAL_INVARIANT')};if($a.decision -eq 'blocked' -and $blocked.Count -eq 0){$issues.Add('BLOCKED_INVARIANT')};if($a.decision -eq 'accepted' -and ($pending.Count -gt 0 -or $blocked.Count -gt 0)){$issues.Add('ACCEPTED_INVARIANT')};if($a.evidencePolicy -ne 'layered-no-cross-layer-flattening'){$issues.Add('EVIDENCE_FLATTENING_POLICY')};if($a.routeKeys -notcontains 'abcd-evidence' -or $a.routeKeys -notcontains 'task-focus-context'){$issues.Add('ROUTE_PROJECTION_MISSING')}
[ordered]@{validator='web-ui-evidence-aggregate';status=if($issues.Count){'blocked'}else{'passed'};findingCount=$issues.Count;findings=@($issues);decision=[string]$a.decision;layerCount=$layers.Count;runtimeStatus='runtime-not-run';nonClaims=@('aggregate-validation-does-not-prove-layer-runtime','accepted-synthetic-fixtures-are-not-runtime-evidence')}|ConvertTo-Json -Depth 8;if($issues.Count){exit 1}
